/**
 * Flags the response with {@code bulkSignupWarning}: {@code true} when more than
 * {@link #BULK_WARNING_THRESHOLD} owners have already been created for this owner's registration day,
 * otherwise {@code false}. The day is the owner's stored (business-day adjusted) registration date, and
 * the count is taken over all owners sharing that date — the same accumulation path as
 * {@link CheckDailyLimit}. Computed per request and mutated onto the loaded owner in place, not persisted.
 */
public class FlagBulkSignup {

    /** Owners created for a single day beyond which the response carries the warning. */
    static final int BULK_WARNING_THRESHOLD = 80;

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        LocalDate businessDay = owner.getRegistrationDate();
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (businessDay != null && businessDay.equals(existing.getRegistrationDate())) {
                count++;
            }
        }
        owner.setBulkSignupWarning(count > BULK_WARNING_THRESHOLD);
    }
}

